Let $d=2$ or $3$, and $2< p<\infty$.
Suppose that $(W_j,\pi_j)$ is a weak solution of (1.6)
with $j=1,\cdots,d$. Then, for any $t>0$,
there holds a decay estimate\textsuperscript{footnote1}
\begin{equation}
\bigg(\int_{Y_f}|\nabla W_j(\cdot, t)|^2\bigg)^{1/2}
\leq C_p t^{-\frac{p}{3p-2}},
\end{equation}
in which the constant $C_p$ depends on $d$, $p$, and the character of
$Y_f$.

Let $d\geq 2$ and $p\geq 2$ be sufficiently large, and $\gamma:=\frac{p(19p-14)}{(3p-2)(7p-2)}$.
Suppose that $(W_j,\pi_j)$ is a weak solution of (1.6) with $j=1,\cdots,d$.
Then, for any $r\in(1,\infty)$,
there exists a constant $q\in(1,\infty)$, such that
$\lambda:=\frac{2(q-r)}{r(q-2)}$ satisfying $0\leq\lambda\leq 1$,
and there holds the decay estimate\textsuperscript{footnote1}
\begin{equation}
\|\partial_t W_j(\cdot,t)\|_{L^r(Y_f)}\lesssim t^{-1+\lambda(1-\gamma)}

\end{equation}
for any $t>0$, where the multiplicative constant depends on $d,p,q$, and the character of $Y_f$.

Let $0<T<\infty$, and $2<p<\infty$ with $\vartheta:= \frac{p}{3p-2}$.
Suppose that $(W_j,\pi_j)$ is a weak solution of (1.6)
with $j=1,\cdots,d,$ and the condition $\int_{Y_f}\pi(\cdot,t)=0$ for any $t> 0$.
Then, for any $\alpha>2\vartheta$,
we have a refined weighted estimate
\begin{equation}
\bigg(\int_{0}^{T}dt\int_{Y_f}|\partial_t W_j(\cdot, t)|^2t^{\alpha}\bigg)^{1/2}
+ \bigg(\int_{0}^{T}dt\int_{Y_f}|\pi_j(\cdot, t)|^2t^{\alpha}\bigg)^{1/2}
\lesssim 1,
\end{equation}
where the up to constant depends on $d$, $\alpha$, $T$, and the character of
$Y_f$.

Let $\vartheta$ be given as in Corollary $3.7$.
Suppose that $(W_j,\pi_j)$ is a weak solution of (1.6)
with $j=1,\cdots,d$. Then,
for any $1<q<\infty$,
there exists a constant $\lambda\in(0,1]$ as the same as in
Lemma $3.6$ such that
a refined decay estimate
\begin{equation}
\bigg(\int_{Y_f}|\nabla W_j(\cdot, t)|^q\bigg)^{1/q}
\lesssim t^{-\frac{1}{2}+\lambda(\frac{1}{2}-\vartheta)}
\end{equation}
holds for any $t>0$, which further leads to
\begin{equation}
\|W_j\|_{L^{2}(0,T;W^{1,q}(Y_f))}\lesssim 1,
\end{equation}
where the up to constant depends on $d$, $q$, $\lambda$, $T$, and the character of $Y_f$.

For any $0<t<T$, let $B(\cdot,t)=\{b_{ij}(\cdot,t)\}_{1\leq i,j\leq d}$
be given as in Propostion $3.1$. Then there hold
the structure properties:
\begin{equation}
\emph{(i)}~~\nabla\cdot B(\cdot,t)=0;\qquad\qquad
\emph{(ii)}~~\int_{Y}B(\cdot,t)=0.
\end{equation}
Moreover, there exists $\Phi(\cdot,t)=\{\Phi_{ki,j}(\cdot,t)\}_{1\leq i,j,k\leq d}$
with $\Phi_{ki,j}(\cdot,t)\in H^{1}_{\emph{loc}}(\mathbb{R}^d)$
being 1-periodic, and satisfying
\begin{equation}
 \nabla \cdot \Phi(\cdot, t) =
 B(\cdot,t)\quad \text{in}\quad Y
\end{equation}
under the antisymmetry condition (i.e., $\Phi_{ki,j}=-\Phi_{ik,j}$).
Also, for any $1<q<\infty$, we have the regularity estimate
\begin{equation}
\|\Phi(\cdot,t)\|_{W^{1,q}(Y)}\lesssim \|B(\cdot,t)\|_{L^q(Y)},
\end{equation}
where the up to constant is independent of $t$.

Let $0<T<\infty$, $d=2$ or $3$, and $1<q<\infty$. Suppose that $(W_j,\pi_j)$ is a weak solution of (1.6)
with $j=1,\cdots,d$.
Then there holds the energy estimate
\begin{equation}
\begin{aligned}
&\|W_j\|_{L^{\infty}(0,T;L^2(Y_f))}+
\|W_j\|_{L^{2}(0,T;H^{1}(Y_f))}\lesssim1,
\end{aligned}
\end{equation}
where the multiplicative constant depends only on $d$ and $T$.
Also, for any $\alpha>(1/3)$,
the weak solution possesses higher regularity estimates:
\begin{subequations}
\begin{align}
\|W_j\|_{L^2(0,T;W^{1,q}(Y_f))}
+\|t^{\alpha}\partial_t W_j\|_{L^2(0,T;L^{2}(Y_f))}
+\|t^{\alpha}\pi_j\|_{L^2(0,T;L^{2}(Y_f)/\mathbb{R})}\lesssim 1;\\
\|\partial_t W_j\|_{L^1(0,T;L^q(Y_f))}
+ \|\nabla^2 W_j\|_{L^1(0,T;L^q(Y_f))}
+ \|\nabla \pi_j\|_{L^1(0,T;L^{q}(Y_f))}\lesssim 1,
\end{align}
\end{subequations}
in which the up to constant relies on $q$, $d$, $T$, and the character of $Y_f$.  Moreover, let
$\tilde{W}_j$ be the zero-extension of $W_j$ on the solid part $Y_s$.




For each $t\in(0,T]$, we can define  $b_{ij}(\cdot,t):=\tilde{W}_j(\cdot,t)\cdot e_i-A_{ij}(t)$.  Then,
there exists $\Phi=\{\Phi_{ki,j}\}_{1\leq i,j,k\leq d}$
with $\Phi_{ki,j}(\cdot,t)\in H^{1}_{\emph{loc}}(\mathbb{R}^d)$,
which is also 1-periodic and satisfies
\begin{equation}
 \nabla_k\Phi_{ki,j}=
 b_{ij}\quad \text{and}\quad
 \Phi_{ki,j}=-\Phi_{ik,j},
\end{equation}
as well as, the following regularity estimates:
\begin{subequations}
\begin{align}
&\|\partial_t\Phi\|_{L^1(0,T;H^1(Y))}
+\|\Phi\|_{L^1(0,T;H^1(Y))}
+\|\Phi(\cdot,0)\|_{H^1(Y)}\lesssim 1;\\
&\|\partial_t\Phi\|_{L^1(0,T;W^{1,q}
(Y))}+\|\Phi\|_{L^1(0,T;W^{1,q}(Y))}
+\|\Phi(\cdot,0)\|_{L^\infty(Y)}
\lesssim 1.

\end{align}
\end{subequations}
Consequently, we also have $\Phi_{ki,j}\in C([0,T];C_{per}(Y))$.

Let $0<T<\infty$. Given $f\in L^2(0,T;C^{1,\frac{1}{2}}(\bar\Omega)^d)$, assume
the same geometry assumptions on perforated domains as in Theorem
$1.2$.
Let $J_1$ and $J_2$ be given as in $(1.17)$. Then, for a.e. $t\geq 0$,
there exists at least
one weak solution to
\begin{equation}
\left\{
\begin{aligned}
\nabla\cdot\xi_{\varepsilon}(\cdot,t)&=\frac{\partial J_2}{\partial t} +\sum_{i} (-_{O_{\varepsilon}^i}\frac{\partial J_1}{\partial t})1_{O_{\varepsilon}^i},&
\text{in}&\quad \Omega_{\varepsilon};\\
\xi_{\varepsilon}(\cdot,t)&=0,&\text{on}&\quad \partial \Omega_{\varepsilon},
\end{aligned}\right.
\end{equation}
where we recall that $1_{O_{\varepsilon}^i}$ is the indicator function of $O_{\varepsilon}^i$, and $\{O_{\varepsilon}^i\}$ is a family of the non-overlap subsets of $O_\varepsilon$, satisfying $(2.5)$. Also,
the solution satisfies the following estimate
\begin{equation}
 \|\xi_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
 + \varepsilon\|\nabla\xi_{\varepsilon}\|_{L^2(0,T;L^2(\Omega_\varepsilon))}
 \lesssim \varepsilon^{1/2}\|f\|_{L^2(0,T;C^{1,1/2}(\bar{\Omega}))},
\end{equation}
in which the up to constant depends on $d$, $|Y_f|$, $T$, and the characters of $Y_f$ and $\Omega$.
}

Assume the same geometry assumptions on the perforated domain
as in Theorem $1.2$. Then, for any $g\in L^2(\Omega_{\varepsilon})$ with
$\int_{\Omega_{\varepsilon}}g =0$,
there exists a vector-valued function
$v_{\varepsilon}\in H^{1}_0(\Omega_{\varepsilon})^d$
such that $\nabla\cdot v_{\varepsilon} =g$ in $\Omega_\varepsilon$, satisfying
\begin{equation}
\| v_{\varepsilon}
\|_{L^2(\Omega_{\varepsilon})}
\leq C\varepsilon\|\nabla v_{\varepsilon}
\|_{L^2(\Omega_{\varepsilon})}
\leq C
\|g\|_{L^2(\Omega_{\varepsilon})},
\end{equation}
where the constant $C$ is independent of $\varepsilon$ and $g$.

Let $\psi_\varepsilon$ be the radial cut-off function defined in
Lemma $4.5$, and $J_2$ be given
as in $(1.17)$. Assume the same conditions as in
Proposition $4.1$. Then,
the first term in the right-hand side of $(4.1)$ satisfies the following estimate
\begin{equation}
\begin{aligned}
\bigg(
\int_{0}^{T}dt\int_{\Omega_{\varepsilon}}
&\big|\frac{\partial J_2}{\partial t}\big|^2
\bigg)^{1/2}
\lesssim
\varepsilon^{\frac{1}{2}}
\Big(\|\partial_t \phi\|_{L^1(0,T;L^2(Y))}
+\|\phi(\cdot,0)\|_{L^2(Y_f)}
\Big)
\|(\nabla G,\varepsilon^{\frac{1}{2}}\nabla^2G)\|_{L^2(0,T;
L^{\infty}(\text{supp}(\psi_{\varepsilon})))}\\
&+
\Big(\|\partial_tA\|_{L^1(0,T)}+|A(0)|\Big)
\bigg\{\varepsilon^{\frac{1}{2}}\|\nabla F\|_{L^2(0,T;C(\bar{\Omega}))}
+\|\nabla(G-F)\|_{
L^2(0,T;L^2{(\text{supp}(\psi_{\varepsilon}))})}\bigg\},\\
\end{aligned}
\end{equation}
where the multiplicative constant depends on
$d$, $|Y_f|$, and the character of $\Omega$,
but independent of $\varepsilon$.

Let $J_1$ be given as in $(1.17)$. Assume the same conditions as in
Proposition $4.1$. Then, there holds
the estimate
\begin{equation}
\begin{aligned}
\bigg(\int_{0}^{T}dt
&\int_{\Omega_{\varepsilon}}\Big|
\sum_{i}(-_{O_{\varepsilon}^i}\frac{\partial J_1}{\partial t}) 1_{O_{\varepsilon}^i}\Big|^2
\bigg)^{1/2} \\
\lesssim
&\varepsilon^{\frac{1}{2}}
\bigg\{\|\partial_t \Phi\|_{L^1(0,T;L^{\infty}(Y))}+
\|\Phi(\cdot,0)\|_{L^{\infty}(Y)}
\bigg\}\|\nabla G\|_{L^2(0,T;L^{\infty}
(O_\varepsilon))},
\end{aligned}
\end{equation}
where the multiplicative constant depends on $d$ and the character of $\Omega$, but independent of $\varepsilon$.
